head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getChildren]<br/>지정한 WebSquare 컴포넌트의 자식 컴포넌트 목록을 조건에 따라 필터링하여 배열로 반환합니다.",
    "validation" : [
        "component(선택) 파라미터로 자식을 검색할 WebSquare 컴포넌트 객체를 설정할 수 있어야 합니다.",
        "component 파라미터를 생략하면 현재 페이지의 Body 요소가 기본값으로 사용되어야 합니다.",
        "options.recursive 가 true 이면 모든 자손 컴포넌트를 재귀적으로 검색해야 합니다.",
        "options.recursive 가 false 이면 직계 자식 컴포넌트만 검색해야 합니다.",
        "조건에 부합하는 WebSquare 컴포넌트 객체들의 배열을 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    if (typeof grp_test !== 'undefined') {
        grp_test.remove();
    }

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // grp_test: 자식 컴포넌트를 가진 그룹
    let strGrpTest = '<xf:group ' + ns + ' style=""></xf:group>';
    scwin.grp_test = await $p.dynamicCreate('grp_test', 'group', strGrpTest, grp_comp);

    // textbox 2개
    let strTxt1 = '<w2:textbox ' + ns + ' label="텍스트1" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child1', 'textbox', strTxt1, scwin.grp_test);

    let strTxt2 = '<w2:textbox ' + ns + ' label="텍스트2" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child2', 'textbox', strTxt2, scwin.grp_test);

    // button 1개
    let strBtn = '<w2:button ' + ns + ' label="버튼1" style=""></w2:button>';
    await $p.dynamicCreate('btn_child1', 'button', strBtn, scwin.grp_test);

    // 하위 그룹 (재귀 검색용)
    let strSubGrp = '<xf:group ' + ns + ' style=""></xf:group>';
    scwin.grp_sub = await $p.dynamicCreate('grp_sub', 'group', strSubGrp, scwin.grp_test);

    // 하위 그룹 안에 textbox 1개
    let strTxt3 = '<w2:textbox ' + ns + ' label="하위텍스트" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_sub1', 'textbox', strTxt3, scwin.grp_sub);
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getChildren_onclick = function () {
    let componentVal = par_component.getValue();
    let recursiveVal = par_recursive.getValue();

    let component;
    if (componentVal === 'grp_test') {
        component = grp_test;
    } else {
        component = undefined;
    }

    let options = {};
    if (recursiveVal !== '') {
        options.recursive = (recursiveVal === 'true');
    }

    let ret;
    if (component) {
        ret = WebSquare.util.getChildren(component, options);
    } else {
        ret = WebSquare.util.getChildren();
    }

    let result = [];
    result.push("자식 수: " + ret.length);

    for (let i = 0; i < ret.length; i++) {
        result.push("[" + i + "] id: " + ret[i].getID());
    }

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
